export const QUESTIONS = RAW.map((r, i) => {
  const [t, o, q, opts, e, s] = r;
  const base = { id: `q${i}`, t, o, q, e, s: s === 'S' };
  if (Array.isArray(opts)) return { ...base, opts, a: 0 };
  return { ...base, ans: opts.ans, unit: opts.unit, tol: opts.tol };
});

const recent = [];
/** Picks n questions for the given sub-topics, mixing static and generated items. */
export function questionsFor(subs, n = 3, tier = 'extended') {
  const want = new Set(subs);
  const statics = shuffle(QUESTIONS.filter((q) => want.has(q.t) && (tier === 'extended' || !q.s) && !recent.includes(q.id)));
  const gens = subs.filter((s) => GEN[s]);
  const out = [];
  const bySub = {};
  for (const q of statics) (bySub[q.t] = bySub[q.t] || []).push(q);
  let guard = 0;
  const order = shuffle(subs);
  while (out.length < n && guard++ < 60) {
    for (const s of order) {
      if (out.length >= n) break;
      const useGen = GEN[s] && (!bySub[s]?.length || Math.random() < 0.4);
      if (useGen) {
        for (let k = 0; k < 6; k++) {
          const g = GEN[s]();
          if (tier !== 'extended' && g.s) continue;
          out.push({ id: `gen-${s}-${Math.random()}`, t: s, gen: true, ...g });
          break;
        }
      } else if (bySub[s]?.length) out.push(bySub[s].shift());
    }
    if (!gens.length && !Object.values(bySub).some((l) => l.length)) break;
  }
  // fall back to recently used if pool ran dry
  if (out.length < n) for (const q of shuffle(QUESTIONS.filter((q) => want.has(q.t) && (tier === 'extended' || !q.s)))) { if (out.length >= n) break; if (!out.includes(q)) out.push(q); }
  for (const q of out) if (!q.gen) { recent.push(q.id); if (recent.length > 40) recent.shift(); }
  return out.slice(0, n);
}

export function coverageReport() {
  const subs = Object.keys(SUB);
  return subs.filter((s) => !QUESTIONS.some((q) => q.t === s) && !GEN[s]);
}
